public class Main {
    static final Object lock = new Object();
    static boolean isDataReady = false;

    public static void main(String[] args) {
        Thread consumer = new Thread(() -> {
            synchronized (lock) {
                while (!isDataReady) { // 1. Check condition
                    try {
                        System.out.println("Consumer waiting...");
                        lock.wait(); // 2. Release lock & Wait
                    } catch (InterruptedException e) {}
                }
                System.out.println("Consumer process data!");
            }
        });

        Thread producer = new Thread(() -> {
            synchronized (lock) {
                System.out.println("Producer preparing data...");
                isDataReady = true;
                lock.notify(); // 3. Wake up waiting thread
            }
        });

        consumer.start();
        try { Thread.sleep(100); } catch (Exception e) {}
        producer.start();
    }
}
